import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        skipinitialspace=False,
    )

    # The first nonblank logical record is the single header row.
    for columns in reader:
        if columns:
            break
    else:
        return {"columns": [], "rows": []}

    width = max(6, len(columns))
    used_names = set(columns)
    while len(columns) < width:
        name = f"column_{len(columns) + 1}"
        while name in used_names:
            name += "_"
        columns.append(name)
        used_names.add(name)

    rows = []
    for row in reader:
        if len(row) < width:
            row.extend([""] * (width - len(row)))
        elif len(row) > width:
            # Treat surplus separators as commas in the definition field,
            # keeping the four leading fields and the trailing source fixed.
            end = len(row) - (width - 5)
            row = row[:4] + [",".join(row[4:end])] + row[end:]
        rows.append(row)

    return {"columns": columns, "rows": rows}
